-- #86 (UX audit 2, N-12): the barber template asked "What are you getting today?" right after
-- the required "What do you need?" service picker. Version 3 rewords the one optional question
-- so it asks for what the picker can't say. Published versions are immutable, so a content change
-- is a new file version and a new row. File: supabase/catalog/barber.json.

insert into app.template_catalog (key, version, payload, tier, mode, health_tagged) values
  ('barber', 3, $catalog${"key":"barber","version":3,"tier":1,"mode":"both","health_tagged":false,"name":{"en":"Barber","es":"Barbería"},"description":{"en":"A walk-in line for cuts, fades and beards, with a line per barber and an \"Anyone available\" option.","es":"Una fila sin cita para cortes, degradados y barbas, con una fila por barbero y la opción \"Cualquiera disponible\"."},"keywords":{"en":["barber","barbershop","haircut","fade","beard","shave"],"es":["barbería","barbero","corte","degradado","barba","afeitado"]},"queues":[{"name":{"en":"Walk-ins","es":"Sin cita"},"prefix":"A","show_eta":true,"services":[{"name":{"en":"Haircut","es":"Corte de pelo"},"minutes":30},{"name":{"en":"Skin fade","es":"Degradado a piel"},"minutes":40},{"name":{"en":"Beard trim","es":"Arreglo de barba"},"minutes":15},{"name":{"en":"Haircut and beard","es":"Corte y barba"},"minutes":45},{"name":{"en":"Kids' cut (under 12)","es":"Corte infantil (menores de 12)"},"minutes":20},{"name":{"en":"Hot towel shave","es":"Afeitado con toalla caliente"},"minutes":30}]}],"resources":[{"label":{"en":"Chair 1","es":"Silla 1"},"kind":"chair"},{"label":{"en":"Chair 2","es":"Silla 2"},"kind":"chair"},{"label":{"en":"Chair 3","es":"Silla 3"},"kind":"chair"}],"providers":{"noun":{"en":"barber","es":"barbero"},"default_count":3,"pool":true},"form":{"name":{"en":"Before your cut","es":"Antes de tu corte"},"fields":[{"key":"style_notes","type":"short_text","label":{"en":"Anything your barber should know?","es":"¿Algo que tu barbero deba saber?"},"help":{"en":"For example \"number 2 on the sides, scissors on top\".","es":"Por ejemplo \"número 2 a los lados, tijera arriba\"."},"sensitivity":"normal"}]},"booking":{"slot_minutes":15,"buffer_after_minutes":5,"min_notice_minutes":30,"max_days_ahead":30}}$catalog$::jsonb, 1, 'both', false);
